def lcm_range(n, t):
    # lcm of n-1, n-2, ..., n-t (with lower bound at 1)
    if t <= 0:
        return 1
    lo = max(1, n - t)
    L = 1
    for k in range(lo, n):
        L = lcm(L, k)
    return L

def generator(rng):
    # Generate a nontrivial, harder-than-seed instance by enforcing t>=2 and a self-consistent fixed point for n via M = m + L(n,t)*(n-1)
    # Retry to keep sizes moderate
    for _ in range(100):
        n_star = rng.randint(12, 40)
        tau = rng.choice([2, 3])
        if tau >= n_star:
            tau = n_star - 1  # ensure deletions are meaningful
        m = rng.randint(1, 9)
        L = lcm_range(n_star, tau)
        # Keep max size moderate
        M = m + L * (n_star - 1)
