        m = int(assign.get('min_element'))
        M = int(assign.get('max_element'))
    except Exception:
        # invalid types
        return (False, None)  # types must be integers
    if tau is None or m is None or M is None:
        return (False, None)  # missing fields
    if tau < 2:
        # We enforce harder-than-seed by requiring tau >= 2
        return (False, None)
    if m <= 0:
        return (False, None)
    if M <= m:
        return (False, None)
    # Compute the greatest feasible n
    n_candidates = []
    # Upper bound for n cannot exceed the total count of integers in [m, M]
    Nmax = M - m + 1
    for n in range(2, Nmax + 1):
        # Only deletions up to min(tau, n-1) matter
        t_eff = min(tau, n - 1)
        L = lcm_range(n, t_eff)
        # For S to contain both m and M and satisfy the congruence constraints induced by all deletions up to t_eff,
        # we must have M ≡ m (mod L)
        if (M - m) % L != 0:
            continue
